(()=>{'use strict';
function peopleSummary(){if(currentTab!=='Irmãos'||document.querySelector('.sv6People'))return;const root=document.getElementById('view'),rows=[...root.querySelectorAll('.brother')];if(!rows.length)return;const box=document.createElement('div');box.className='sv6People';box.innerHTML=`<span>Quórum</span><b>${rows.length} irmãos na lista atual</b><small>Use a busca para localizar rapidamente um irmão.</small>`;const search=root.querySelector('.sbSearch');(search||root.firstElementChild)?.insertAdjacentElement(search?'afterend':'beforebegin',box)}
function removeLegacyVisits(){document.querySelectorAll('.sv6Visits').forEach(x=>x.remove())}
function run(){try{removeLegacyVisits();peopleSummary()}catch(e){console.warn('safe bundle v6 skipped',e)}}
const old=window.renderTab;if(typeof old==='function')window.renderTab=function(){const r=old.apply(this,arguments);setTimeout(run,35);return r};
new MutationObserver(()=>requestAnimationFrame(removeLegacyVisits)).observe(document.getElementById('view'),{childList:true,subtree:true});
document.addEventListener('DOMContentLoaded',()=>setTimeout(run,60));
const s=document.createElement('style');s.textContent=`.sv6Visits{display:none!important}.sv6People{background:var(--ios-card,#fff);border-radius:16px;margin-bottom:14px;padding:16px 18px}.sv6People span,.sv6People b,.sv6People small{display:block}.sv6People span{font-size:10px;text-transform:uppercase;letter-spacing:.055em;color:var(--teal);font-weight:750}.sv6People b{font-size:16px;margin-top:3px}.sv6People small{margin-top:3px}`;document.head.appendChild(s)})();